<div class="mb-3"><label for="current_password" class="form-label">Password lama</label><input id="current_password" type="password" name="current_password" class="form-control" autocomplete="current-password" required></div>
<div class="mb-3"><label for="password" class="form-label">Password baru</label><input id="password" type="password" name="password" class="form-control" autocomplete="new-password" minlength="8" required><small class="text-muted">Minimal 8 karakter, huruf besar, huruf kecil, angka, dan simbol (@$!%*?&).</small></div>
<div class="mb-3"><label for="password_confirmation" class="form-label">Konfirmasi password baru</label><input id="password_confirmation" type="password" name="password_confirmation" class="form-control" autocomplete="new-password" minlength="8" required></div>
